import numpy as np
from collections import Counter
def solve(g):
    cnt=Counter(map(int,g.flatten()))
    bg=cnt.most_common(1)[0][0]
    acc=[v for v in cnt if v!=bg and cnt[v]>1]
    acc=acc[0] if len(acc)==1 else None
    out=g.copy()
    H,W=len(out),len(out[0])
    def line(i,j):
        return all(out[i,k]==acc for k in range(W)) or all(out[k,j]==acc for k in range(H))
    for i in range(H):
        for j in range(W):
            if (out[i,j]==acc) and ((i==0 or line(i-1,0)) and (j==0 or line(0,j-1))):
                out[i,j]=2
    # simpler: full accent rows/cols only
    out2=g.copy()
    for i in range(H):
        if all(out2[i][k]==acc for k in range(W)): out2[i]=[2]*W
    for j in range(W):
        if all(out2[k][j]==acc for k in range(H)): out2[:,j]=2
    return out2.tolist()
